function urlNovelsRecommendDetailed(nidList) {
    if (nidList.length >= 9) nidList.length = 9
    return `https://www.pixiv.net/ajax/novel/recommend/novels?${nidList.map(v => `novelIds[]=${v}`).join("&")}`
