    if (!settings) settings = this.setDefaultSettings()
    if (settings.IPDirect) {
        url = url.replace("http://", "https://").replace("www.pixiv.net", "210.140.139.155")
        let headers = {
            "User-Agent": this.getFromCache("userAgent"),
            "X-Requested-With": "XMLHttpRequest",
