        link = targetFunc(illustId).trim()
        if (link && !settings.DEBUG) {
            this.putInCache(urlIllustDetailed(illustId), link, cacheSaveSeconds)
        }
    }
    return this.urlPxImgUrl(link.replace(`_p0`, `_p${order - 1}`))
